-- ChubbyLu Bakery POS v0.14.0 — suppliers and audited stock receiving
create table if not exists public.suppliers(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,name text not null,contact_name text,phone text,email text,active boolean not null default true,created_at timestamptz not null default now(),unique(shop_id,name));
create table if not exists public.stock_receipts(id uuid primary key default gen_random_uuid(),shop_id uuid not null references public.shops(id) on delete cascade,supplier_id uuid not null references public.suppliers(id) on delete restrict,product_id uuid not null references public.products(id) on delete restrict,quantity numeric(12,3) not null check(quantity>0),unit_cost numeric(12,2) not null check(unit_cost>=0),total_cost numeric(12,2) generated always as(round(quantity*unit_cost,2)) stored,invoice_reference text,note text,received_by uuid not null references auth.users(id) on delete restrict,received_at timestamptz not null default now());
create index if not exists stock_receipts_shop_date_idx on public.stock_receipts(shop_id,received_at desc);alter table public.suppliers enable row level security;alter table public.stock_receipts enable row level security;create policy suppliers_admin_select on public.suppliers for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());create policy stock_receipts_admin_select on public.stock_receipts for select to authenticated using(shop_id=public.current_shop_id() and public.is_admin());

create or replace function public.create_supplier(p_name text,p_contact_name text default null,p_phone text default null,p_email text default null) returns uuid language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_id uuid;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if nullif(trim(p_name),'') is null then raise exception 'Supplier name is required';end if;insert into public.suppliers(shop_id,name,contact_name,phone,email) values(v_shop,trim(p_name),nullif(trim(p_contact_name),''),nullif(trim(p_phone),''),nullif(lower(trim(p_email)),'') ) returning id into v_id;return v_id;end $$;

create or replace function public.receive_stock(p_supplier_id uuid,p_product_id uuid,p_quantity numeric,p_unit_cost numeric,p_invoice_reference text default null,p_note text default null,p_update_product_cost boolean default true) returns jsonb language plpgsql security definer set search_path=public as $$declare v_shop uuid:=public.current_shop_id();v_receipt uuid;v_stock numeric;v_cost numeric;v_supplier text;begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_quantity is null or p_quantity<=0 or p_unit_cost is null or p_unit_cost<0 then raise exception 'Valid quantity and unit cost are required';end if;select name into v_supplier from public.suppliers where id=p_supplier_id and shop_id=v_shop and active;if v_supplier is null then raise exception 'Active supplier not found';end if;perform 1 from public.products where id=p_product_id and shop_id=v_shop for update;if not found then raise exception 'Product not found';end if;insert into public.stock_receipts(shop_id,supplier_id,product_id,quantity,unit_cost,invoice_reference,note,received_by) values(v_shop,p_supplier_id,p_product_id,p_quantity,round(p_unit_cost,2),nullif(trim(p_invoice_reference),''),nullif(trim(p_note),''),auth.uid()) returning id into v_receipt;update public.products set stock=stock+p_quantity,cost_price=case when p_update_product_cost then round(p_unit_cost,2) else cost_price end,updated_at=now() where id=p_product_id returning stock,cost_price into v_stock,v_cost;insert into public.inventory_adjustments(shop_id,product_id,delta,reason,created_by) values(v_shop,p_product_id,p_quantity,'Stock receipt from '||v_supplier||coalesce(' • Invoice '||nullif(trim(p_invoice_reference),''),''),auth.uid());return jsonb_build_object('receipt_id',v_receipt,'product_id',p_product_id,'new_stock',v_stock,'cost_price',v_cost);end $$;

create or replace function public.get_stock_receiving() returns jsonb language plpgsql security definer stable set search_path=public as $$declare v_shop uuid:=public.current_shop_id();begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;return jsonb_build_object('suppliers',(select coalesce(jsonb_agg(to_jsonb(x) order by x.name),'[]'::jsonb) from(select id,name,contact_name,phone,email,active from public.suppliers where shop_id=v_shop)x),'receipts',(select coalesce(jsonb_agg(to_jsonb(x) order by x.received_at desc),'[]'::jsonb) from(select r.id,r.received_at,s.name supplier_name,p.name product_name,r.quantity,r.unit_cost,r.total_cost,r.invoice_reference,r.note,coalesce(sp.display_name,'Former staff') received_by_name from public.stock_receipts r join public.suppliers s on s.id=r.supplier_id join public.products p on p.id=r.product_id left join public.staff_profiles sp on sp.user_id=r.received_by and sp.shop_id=r.shop_id where r.shop_id=v_shop order by r.received_at desc limit 100)x));end $$;
revoke all on function public.create_supplier(text,text,text,text) from public;revoke all on function public.receive_stock(uuid,uuid,numeric,numeric,text,text,boolean) from public;revoke all on function public.get_stock_receiving() from public;grant execute on function public.create_supplier(text,text,text,text) to authenticated;grant execute on function public.receive_stock(uuid,uuid,numeric,numeric,text,text,boolean) to authenticated;grant execute on function public.get_stock_receiving() to authenticated;
